    StopEngine,
    AuthStatus,
    SignIn,
    SignInHeadless,
    CompleteSignIn,
    SignOut,
    ListOrgs,
    CreateOrg,
    SelectOrg,
    /// One-time local→synced profile import: what's importable (unary).
    LocalImportStatus,
