    ImportLocalWorkspace,
    ListRepos,
    AddRepo,
    CloneRepo,
    CreateRepo,
    ListBranches,
    ListRefs,
    ListGitHistory,
    /// Fuzzy commit-subject / SHA search over the complete public history.
    SearchGitHistory,
    /// Resolve hosted profile images for a page of Git commit authors.
    ResolveGitAvatars,
    /// Update remote-tracking refs without changing HEAD, the index, or files.
    FetchAll,
    SwitchRef,
    ListFolders,
    /// The device's browse roots: home plus mounted drives/volumes.
    ListDrives,
    /// Fuzzy relative-path search rooted in a known chat or space checkout.
    SearchFiles,
    ListWorkspaceDirectory,
    SearchWorkspaceFiles,
    ReadWorkspaceImage,
    ReadWorkspaceFile,
    MoveWorkspaceEntry,
    DeleteWorkspaceEntry,
    WriteWorkspaceFile,
    WatchWorkspaceFiles,
