    /// Whether the engine answers with `{id,item}*` frames instead of one `{id,ok}`.
    pub fn kind(m: Method) Kind {
        return switch (m) {
            .AuthStatus,
            .ImportLocalWorkspace,
            .SubscribeTerminal,
            .UpdateStatus,
            .WatchChats,
            .WatchCheckoutChangeRequest,
            .WatchCheckoutDiffs,
